import{ENV}from"../index.js";const TAG="⚡ _AYOBOT v1_ | 👑 _AYOCODES_";export async function sendMsg(e,t,n,s={}){try{if(!e||!t)return null;let i={};i="string"==typeof n?{text:n}:n.text?{text:n.text}:n.image?{image:n.image,caption:n.caption||"",...n.mentions&&{mentions:n.mentions}}:n.video?{video:n.video,caption:n.caption||"",...n.mentions&&{mentions:n.mentions}}:n.audio?{audio:n.audio,mimetype:n.mimetype||"audio/mpeg",ptt:n.ptt||!1}:n.document?{document:n.document,fileName:n.fileName||"file",caption:n.caption||"",mimetype:n.mimetype||"application/octet-stream"}:n.sticker?{sticker:n.sticker}:n;return await e.sendMessage(t,{...i,...s})}catch(e){return console.error(`[sendMsg] Error: ${e.message}`),null}}export async function sendReply(e,t,n,s={}){const i=t.key?.remoteJid;if(!i)return null;return sendMsg(e,i,n,{...s,quoted:t})}export async function sendTyping(e,t){try{await e.sendPresenceUpdate("composing",t)}catch(e){}}export async function sendRecording(e,t){try{await e.sendPresenceUpdate("recording",t)}catch(e){}}export async function sendPaused(e,t){try{await e.sendPresenceUpdate("paused",t)}catch(e){}}export function createButtonMessage(e,t,n=TAG){return{text:e,footer:n,buttons:t.map((e,t)=>({buttonId:e.id||`btn_${t}`,buttonText:{displayText:e.text},type:1})),headerType:1}}export function createListMessage(e,t,n=TAG){return{text:e,footer:n,title:e,buttonText:"Select Option",sections:t.map(e=>({title:e.title,rows:e.rows.map(e=>({title:e.title,description:e.description||"",rowId:e.id}))}))}}export default{sendMsg:sendMsg,sendReply:sendReply,sendTyping:sendTyping,sendRecording:sendRecording,sendPaused:sendPaused,createButtonMessage:createButtonMessage,createListMessage:createListMessage};